package com.vandorlabs.neoforge.trapdoor;

import com.mojang.serialization.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.attachment.AttachmentType;
import net.neoforged.neoforge.event.server.ServerStartedEvent;

/** Actual platform persistent/attachment data, including a failure after superclass persistent installation. */
@EventBusSubscriber(modid="vandorlabs")
public final class TrapdoorLoadGuardChecks {
 private static final BlockPos BASE=new BlockPos(3648,80,3648);private static final Housing[] BLOCKS=new Housing[2];private static final BlockEntityType<?>[] TYPES=new BlockEntityType[2];private static AttachmentType<String> attachment;private static int checks;
 private static boolean enabled(){return System.getProperty("vandorlabs.transmitterPhase","").startsWith("trapdoor-load-guard-");}
 private static void need(boolean yes,String message){checks++;if(!yes)throw new AssertionError("Trapdoor load guard: "+message);}
 private static final class Housing extends NativeTrapdoorBlock {final int family;Housing(int family){super(BlockBehaviour.Properties.of().strength(3).requiresCorrectToolForDrops().noOcclusion().dynamicShape(),family==1);this.family=family;}protected MapCodec<? extends BaseEntityBlock> codec(){return MapCodec.unit(this);}protected BlockEntityType<?> entityType(){return TYPES[family];}@Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return new Probe(TYPES[family],pos,state);}}
 private static final class Probe extends NativeTrapdoorEntity {Probe(BlockEntityType<?> type,BlockPos pos,BlockState state){super(type,pos,state);}@Override public com.vandorlabs.redstone.ChannelList transmittedChannels(){return getRedstoneChannels();}@Override public int transmissionRange(){return 32;}}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!enabled())return;event.register(Registries.BLOCK,h->{for(int i=0;i<2;i++){BLOCKS[i]=new Housing(i);h.register(ResourceLocation.parse("vandorlabs:trapdoor_guard_fixture_"+i),BLOCKS[i]);}});event.register(Registries.ITEM,h->{for(int i=0;i<2;i++)h.register(ResourceLocation.parse("vandorlabs:trapdoor_guard_fixture_"+i),new NativeTrapdoorItem(BLOCKS[i],new net.minecraft.world.item.Item.Properties()));});event.register(Registries.BLOCK_ENTITY_TYPE,h->{for(int i=0;i<2;i++){final int family=i;TYPES[i]=BlockEntityType.Builder.of((p,s)->new Probe(TYPES[family],p,s),BLOCKS[i]).build(null);h.register(ResourceLocation.parse("vandorlabs:trapdoor_guard_fixture_"+i),TYPES[i]);}});event.register(net.neoforged.neoforge.registries.NeoForgeRegistries.Keys.ATTACHMENT_TYPES,h->{attachment=AttachmentType.builder(()->"default").serialize(Codec.STRING).build();h.register(ResourceLocation.parse("vandorlabs:trapdoor_guard_attachment"),attachment);});}}
 private static CompoundTag data(boolean platform){var tag=new CompoundTag();tag.putInt("housingTexture",0);tag.putInt("TrapdoorTrigger",0);tag.putIntArray("RedstoneChannels",new int[]{91});tag.putString("ForeignRoot","retain:opaque");if(platform){var nativeData=new CompoundTag();nativeData.putString("OriginalNative","from-load");tag.put("NeoForgeData",nativeData);var attachments=new CompoundTag();attachments.putString("vandorlabs:trapdoor_guard_attachment","from-load");tag.put("neoforge:attachments",attachments);}return tag;}
 private static NativeTrapdoorEntity put(ServerLevel level,BlockPos pos,int family){level.setBlock(pos,BLOCKS[family].defaultBlockState(),18);return (NativeTrapdoorEntity)level.getBlockEntity(pos);}
 private static final class PartialFailureTag extends CompoundTag {int copies;PartialFailureTag(CompoundTag tag){merge(tag);}@Override public CompoundTag copy(){var plain=super.copy();return ++copies==2?new FailureCopy(plain):plain;}}
 private static final class FailureCopy extends CompoundTag {FailureCopy(CompoundTag tag){merge(tag);}@Override public CompoundTag getCompound(String key){return key.equals("neoforge:attachments")?new ThrowingAttachments():super.getCompound(key);}}
 private static final class ThrowingAttachments extends CompoundTag {@Override public Set<String> getAllKeys(){throw new IllegalStateException("fixture failure after platform persistent data installed");}}
 private static void components(ServerLevel level,NativeTrapdoorEntity tile,int family){
  tile.loadWithComponents(data(true),level.registryAccess());
  tile.setComponents(net.minecraft.core.component.DataComponentMap.builder().set(net.minecraft.core.component.DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("live-name")).build());
  var valid=tile.saveWithoutMetadata(level.registryAccess());tile.loadWithComponents(valid,level.registryAccess());need(tile.components().get(net.minecraft.core.component.DataComponents.CUSTOM_NAME).getString().equals("live-name"),"actual platform component loaded family="+family);
  tile.setComponents(net.minecraft.core.component.DataComponentMap.EMPTY);need(!tile.saveWithoutMetadata(level.registryAccess()).getCompound("components").contains("minecraft:custom_name"),"live component deletion stays deleted family="+family);
  for(boolean malformed:new boolean[]{false,true}){
   tile.loadWithComponents(valid,level.registryAccess());var bad=valid.copy();
   if(malformed)bad.putString("components","opaque:future-map");else bad.getCompound("components").putString("missing_mod:unknown_component","opaque:component");
   var original=bad.copy();tile.loadWithComponents(bad,level.registryAccess());
   need(tile.inert()&&tile.trapdoorVisual()==null,"unsupported component envelope refuses authoritative installation family="+family+" malformed="+malformed);
   need(tile.saveWithoutMetadata(level.registryAccess()).equals(original),"final component encoder preserves full inert original family="+family+" malformed="+malformed);
   need(!tile.getUpdateTag(level.registryAccess()).contains("components"),"inert component privacy family="+family);
  }
 }
 private static BlockPos watchedDrop;private static net.minecraft.world.item.Item watchedItem;private static int observedDrops;private static net.minecraft.world.item.ItemStack observedStack=net.minecraft.world.item.ItemStack.EMPTY;private static final List<net.minecraft.world.entity.item.ItemEntity> observedEntities=new ArrayList<>();
 @SubscribeEvent public static void drop(net.neoforged.neoforge.event.entity.EntityJoinLevelEvent event){if(enabled()&&watchedDrop!=null&&event.getEntity() instanceof net.minecraft.world.entity.item.ItemEntity item&&item.getItem().is(watchedItem)&&item.position().distanceToSqr(net.minecraft.world.phys.Vec3.atCenterOf(watchedDrop))<16){observedDrops+=item.getItem().getCount();observedStack=item.getItem().copy();observedEntities.add(item);}}
 private static void recoveryMining(ServerLevel level,int family){
  var pos=BASE.east(family*4).south(8);var target=pos.south(4);var actor=new net.neoforged.neoforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(new UUID(0,774+family),"TrapdoorRecovery"));actor.getInventory().selected=0;actor.setPos(pos.getX()+.5,pos.getY(),pos.getZ()-2);
  var bad=data(true);bad.putInt("NativeTrapdoorLinks",2);var item=BLOCKS[family].asItem();need(item instanceof NativeTrapdoorItem,"registered recovery item");
  for(boolean creative:new boolean[]{false,true})for(boolean proper:new boolean[]{false,true}){
   var tile=put(level,pos,family);tile.loadWithComponents(bad,level.registryAccess());need(tile.inert(),"inert mining fixture");actor.setGameMode(creative?net.minecraft.world.level.GameType.CREATIVE:net.minecraft.world.level.GameType.SURVIVAL);actor.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.item.ItemStack(proper?net.minecraft.world.item.Items.WOODEN_PICKAXE:net.minecraft.world.item.Items.WOODEN_SHOVEL));
   if(!creative)need(level.getBlockState(pos).canHarvestBlock(level,pos,actor)==proper,"real proper/wrong tool fixture");
   watchedDrop=pos;watchedItem=item;observedDrops=0;observedStack=net.minecraft.world.item.ItemStack.EMPTY;observedEntities.clear();
   need(actor.gameMode.destroyBlock(pos)&&level.isEmptyBlock(pos),"real failed-owner mining");watchedDrop=null;var recovery=observedStack;for(var entity:observedEntities)entity.discard();
   need(observedDrops==1,"one opaque recovery owner creative="+creative+" proper="+proper+" actual="+observedDrops);need(NativeTrapdoorItem.configuration(recovery).getCompound(NativeTrapdoorItem.OPAQUE_RECOVERY).equals(bad),"harvest retains exact failed platform snapshot");
   actor.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);level.setBlock(target,Blocks.AIR.defaultBlockState(),18);level.setBlock(target.below(),Blocks.STONE.defaultBlockState(),18);actor.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,recovery);int before=recovery.getCount();var result=recovery.useOn(new net.minecraft.world.item.context.UseOnContext(actor,net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atBottomCenterOf(target),Direction.UP,target.below(),false)));
   need(!result.consumesAction()&&recovery.getCount()==before&&level.isEmptyBlock(target),"opaque recovery refuses placement without consuming original");
  }
 }
 private static void write(ServerLevel level){for(int family=0;family<2;family++){var pos=BASE.east(family*4);recoveryMining(level,family);var tile=put(level,pos,family);components(level,tile,family);var good=data(true);var original=good.copy();tile.loadWithComponents(good,level.registryAccess());need(!tile.inert(),"valid platform data loads family="+family);tile.getPersistentData().putString("LiveEdit","current");tile.setData(attachment,"current");need(good.equals(original),"superclass state cannot alias original input family="+family);var saved=tile.saveWithoutMetadata(level.registryAccess());need(saved.getCompound("NeoForgeData").getString("LiveEdit").equals("current")&&saved.getCompound("neoforge:attachments").getString("vandorlabs:trapdoor_guard_attachment").equals("current"),"live platform edits replace old serialized values");tile.getPersistentData().remove("OriginalNative");tile.removeData(attachment);saved=tile.saveWithoutMetadata(level.registryAccess());need(!saved.getCompound("NeoForgeData").contains("OriginalNative")&&!saved.getCompound("neoforge:attachments").contains("vandorlabs:trapdoor_guard_attachment"),"valid platform deletions do not resurrect retained fields");
  good=data(true);tile.loadWithComponents(good,level.registryAccess());tile.setData(attachment,"stale-before-codec");var codecFailure=data(true);codecFailure.getCompound("neoforge:attachments").putInt("vandorlabs:trapdoor_guard_attachment",42);tile.loadWithComponents(codecFailure,level.registryAccess());need(tile.inert()&&tile.saveWithoutMetadata(level.registryAccess()).equals(codecFailure),"caught actual attachment codec failure retains original over stale live map");
  for(boolean platform:new boolean[]{false,true}){good=data(true);tile.loadWithComponents(good,level.registryAccess());tile.getPersistentData().putString("OldLive","must-not-leak");tile.setData(attachment,"old-live");var bad=data(platform);bad.putInt("NativeTrapdoorLinks",2);original=bad.copy();tile.loadWithComponents(bad,level.registryAccess());tile.getPersistentData().putString("AfterFailure","must-not-leak");need(tile.inert()&&tile.trapdoorVisual()==null&&!tile.isChannelMemberActive(),"future schema remains inert");need(bad.equals(original),"failed input stays unchanged");need(tile.saveWithoutMetadata(level.registryAccess()).equals(original),"future failure retains original full platform snapshot family="+family+" present="+platform);need(!tile.getUpdateTag(level.registryAccess()).contains("NeoForgeData")&&!tile.getUpdateTag(level.registryAccess()).contains("neoforge:attachments"),"inert public update excludes private platform data");}
  var partial=data(true);partial.putInt("NativeTrapdoorLinks",1);var injected=new PartialFailureTag(partial);var before=tile.settings();tile.loadWithComponents(injected,level.registryAccess());need(tile.inert()&&tile.failureReason().contains("fixture failure"),"real superclass partial load is guarded");need(tile.getPersistentData().getString("OriginalNative").equals("from-load"),"fault follows actual superclass persistent installation");tile.getPersistentData().putString("HalfInstalled","must-not-save");need(tile.settings()==before&&injected.equals(partial)&&tile.saveWithoutMetadata(level.registryAccess()).equals(partial),"partial superclass/runtime state cannot overwrite retained original");
  tile.loadWithComponents(data(true),level.registryAccess());level.setBlock(pos.north(),Blocks.REDSTONE_BLOCK.defaultBlockState(),18);com.vandorlabs.neoforge.redstone.NativeRedstoneChannels.channelsChanged(tile);need(com.vandorlabs.neoforge.redstone.NativeRedstoneChannels.level(level,pos,91)==15,"live owner contributes to native bank");var bad=data(true);bad.putInt("NativeTrapdoorLinks",2);tile.loadWithComponents(bad,level.registryAccess());tile.tickServer();need(com.vandorlabs.neoforge.redstone.NativeRedstoneChannels.level(level,pos,91)==0,"deferred failed-owner phase withdraws old bank output");need(tile.saveWithoutMetadata(level.registryAccess()).equals(bad),"bank cleanup leaves original failure snapshot unchanged");
 }}
 private static void read(ServerLevel level){for(int family=0;family<2;family++){var tile=(NativeTrapdoorEntity)level.getBlockEntity(BASE.east(family*4));need(tile!=null&&tile.inert(),"future snapshot remains inert after process restart");var expected=data(true);expected.putInt("NativeTrapdoorLinks",2);var saved=tile.saveWithoutMetadata(level.registryAccess());if(saved.contains("keepPacked")){need(saved.contains("keepPacked",Tag.TAG_BYTE)&&!saved.getBoolean("keepPacked"),"loaded chunk storage marker");saved.remove("keepPacked");}need(saved.equals(expected),"full original platform snapshot survives process restart");}}
 @SubscribeEvent public static void start(ServerStartedEvent event){if(!enabled())return;try{var level=event.getServer().overworld();for(int x=227;x<=229;x++)for(int z=227;z<=229;z++){level.getChunk(x,z);level.setChunkForced(x,z,true);}boolean read=System.getProperty("vandorlabs.transmitterPhase","").endsWith("-read");if(read)read(level);else write(level);System.out.println("[vandorlabs][trapdoor-load-guard] "+(read?"read":"write")+" PASS checks="+checks);}catch(Throwable failure){System.err.println("[vandorlabs][trapdoor-load-guard] FAIL "+failure);failure.printStackTrace();}finally{event.getServer().halt(false);}}
}
